/// Makes an exe0 API token locally, without a request.
///
/// key is the path of an SSH private key on your exe.dev account (`ssh
/// exe.dev ssh-key add`), or of its public key when ssh-agent holds the
/// private key; a leading `~/` is your home directory. Removing the key from
/// your account revokes every token it signed. It is signed with `ssh-keygen
/// -Y sign`, which must be installed, and asks for the key's passphrase if it
/// has one.
///
/// The builder sets the token's claims; see
/// <https://exe.dev/docs/https-api#granular-permissions>. Without
/// [`cmds`](SignToken::cmds), a token may run a default set of commands that
/// includes new, ls, and whoami, but not ssh or rm.
///
/// ```no_run
/// # fn f() -> exedev::Result<()> {
/// use std::time::Duration;
/// let token = exedev::sign_token("~/.ssh/id_ed25519")
///     .cmds(["new", "ls", "ssh", "rm"])
///     .expires_in(Duration::from_secs(3600))
///     .sign()?;
/// let exe = exedev::Client::new(token)?;
/// # Ok(()) }
/// ```
pub fn sign_token(key: impl AsRef<Path>) -> SignToken {
    SignToken {
        key: key.as_ref().to_path_buf(),
        claims: Map::new(),
        payload: None,
        vm: None,
        namespace: None,
        ssh_keygen: "ssh-keygen".into(),
        err: None,
    }
}

